import{_ as a,o,c as n,a0 as r}from"./chunks/framework.D9r9xKZM.js";const m=JSON.parse('{"title":"🔬 La Guerra Invisible","description":"","frontmatter":{},"headers":[],"relativePath":"guerra-invisible.md","filePath":"guerra-invisible.md"}'),s={name:"guerra-invisible.md"};function i(t,e,d,l,p,u){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="🔬-la-guerra-invisible" tabindex="-1">🔬 La Guerra Invisible <a class="header-anchor" href="#🔬-la-guerra-invisible" aria-label="Permalink to &quot;🔬 La Guerra Invisible&quot;">​</a></h1><hr><h2 id="title-mi-duro-camino-por-la-eii" tabindex="-1">title: Mi duro camino por la EII <a class="header-anchor" href="#title-mi-duro-camino-por-la-eii" aria-label="Permalink to &quot;title: Mi duro camino por la EII&quot;">​</a></h2><h1 id="mi-duro-camino-por-la-eii-de-la-incomprension-a-la-remision" tabindex="-1">Mi duro camino por la EII: de la incomprensión a la remisión <a class="header-anchor" href="#mi-duro-camino-por-la-eii-de-la-incomprension-a-la-remision" aria-label="Permalink to &quot;Mi duro camino por la EII: de la incomprensión a la remisión&quot;">​</a></h1><p><strong>Todo empezó cuando me levanté un día y no fui al baño bien. Era la primera vez que hacía distinto.</strong></p><p>Me empezó a doler el estómago cada vez que iba, y empecé a sangrar. No podía andar, necesitaba estar en la cama. Iba de 8 a 10 veces al día al baño. Lloraba constantemente, me sentía ultra incomprendida, dando palos de ciego.</p><p>Perdí 10 kilos, pesaba 45. Mi cuerpo solo aceptaba sopa y arroz, y a veces ni eso. No podía ni beber agua, me sentaba fatal.</p><p>Pasaron 4 meses.</p><h2 id="_4-meses-de-pruebas-y-espera" tabindex="-1">4 meses de pruebas y espera <a class="header-anchor" href="#_4-meses-de-pruebas-y-espera" aria-label="Permalink to &quot;4 meses de pruebas y espera&quot;">​</a></h2><p>Me hicieron colonoscopia, la prueba del Helicobacter pylori y una resonancia magnética. Encima, <strong>di positivo en Helicobacter pylori</strong> y me la tuvieron que tratar con antibióticos, lo que me agravó más la EII porque los antibióticos hacían contra, pero era eso o seguir estando peor por ambas cosas.</p><p>Sentí mucho miedo porque no sabía qué pasaba. Necesitaba ponerle nombre y apellido a lo que tenía.</p><p><strong>Fue entonces cuando me diagnosticaron la Enfermedad de Crohn.</strong></p><h2 id="nadie-me-creia-pon-de-tu-parte" tabindex="-1">Nadie me creía: &quot;pon de tu parte&quot; <a class="header-anchor" href="#nadie-me-creia-pon-de-tu-parte" aria-label="Permalink to &quot;Nadie me creía: &quot;pon de tu parte&quot;&quot;">​</a></h2><p>Mi familia se pensaba al principio que exageraba y que no ponía de mi parte. Cuando me dolía todo el cuerpo, no tenía fuerzas, se me caía el pelo, no podía comer…</p><p>Frases que me dolieron: <strong>&quot;pon de tu parte&quot;</strong>, <strong>&quot;no te inventes cosas que no tienes&quot;</strong>, <strong>&quot;tienes que salir de la cama&quot;</strong>.</p><p>Eso afectó a mal. Y me di cuenta de que, en el fondo, <strong>realmente quien te acompaña eres tú mismo o tú misma</strong> y es quien más te quiere y te comprende.</p><h2 id="_9-medicaciones-y-3-anos-de-desesperacion" tabindex="-1">9 medicaciones y 3 años de desesperación <a class="header-anchor" href="#_9-medicaciones-y-3-anos-de-desesperacion" aria-label="Permalink to &quot;9 medicaciones y 3 años de desesperación&quot;">​</a></h2><p>Probé 9 medicaciones. Mesalazina, paracetamol, prednisona, un biológico de por medio que me lo agravó todo… hasta que di con el <strong>Ustekinumab</strong> (que fue el que hizo posible que estuviera contando esto desde otra perspectiva).</p><p>El proceso fue que me tiré casi <strong>3 años</strong> hasta que me lo mandaron. Llamar continuamente a la unidad de Digestivo porque no me mejoraba con las otras medicaciones y sangraba más… era desesperante.</p><p>Entre medias también hacía visitas a otros especialistas: al reumatólogo, con el resultado de que con el Crohn me dio <strong>espondiloartritis periférica</strong>, de la cual también me estoy tratando actualmente con Nordimet.</p><h2 id="los-sintomas-que-nadie-ve" tabindex="-1">Los síntomas que nadie ve <a class="header-anchor" href="#los-sintomas-que-nadie-ve" aria-label="Permalink to &quot;Los síntomas que nadie ve&quot;">​</a></h2><p>He tenido desde más sangrados, a caída del pelo, 0% fuerza, temblores.</p><p><strong>Dolor, llanto e incertidumbre. Me he sentido como una cobaya.</strong></p><h2 id="un-mensaje-para-ti-que-estas-leyendo-esto" tabindex="-1">Un mensaje para ti que estás leyendo esto <a class="header-anchor" href="#un-mensaje-para-ti-que-estas-leyendo-esto" aria-label="Permalink to &quot;Un mensaje para ti que estás leyendo esto&quot;">​</a></h2><p>Si estás leyendo esto y estás en el punto más bajo, <strong>quiero que sepas que yo también estuve ahí.</strong></p><p>No estás loco o loca. No exageras. Tu cuerpo te está pidiendo ayuda, y tienes derecho a buscar respuestas hasta encontrarlas.</p><p><strong>Yo lo hice. Tú también puedes.</strong></p><hr>',28)])])}const b=a(s,[["render",i]]);export{m as __pageData,b as default};
